import java.math.BigInteger;
import java.util.Scanner;

public class sd5 {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int w = s.nextInt();
        int m = s.nextInt();

        long temp = m;
        int stop = 0;
        while (temp > 0) {
            if (stop == 40) {
                throw new ArrayIndexOutOfBoundsException(stop);
            }
            temp /= w;
            stop++;
        }

        BigInteger cur = BigInteger.valueOf(m);
        BigInteger wBig = BigInteger.valueOf(w);
        boolean flag = true;

        for (int i = 0; i <= stop; i++) {
            int d;
            if (cur.signum() <= 0) {
                d = 0;
                cur = BigInteger.ZERO;
            } else {
                d = cur.remainder(wBig).intValue();
                cur = cur.divide(wBig);
                if (d == w || d == w - 1) {
                    cur = cur.add(BigInteger.ONE);
                }
            }

            if (d != 0 && d != 1 && d != w && d != w - 1) {
                flag = false;
                break;
            }

            if (i == stop) {
                break;
            }
        }

        System.out.println(flag ? "YES" : "NO");
    }
}
